from pathlib import Path
from html import escape

ROOT=Path(__file__).parent
NAV=[('Home','home.html'),('Blog','blog.html'),('About','about.html'),('Contact','contact.html')]
def page(file,title,photo,content,current=''):
    links=''.join(f'<a href="{url}"'+(' aria-current="page"' if name==current else '')+f'>{name}</a>' for name,url in NAV)
    html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Wildflower Collectives</title><meta name="description" content="A personal blog about growth, healing, spiritual awakening, and the moments, people, and words that change us."><meta name="theme-color" content="#17131c"><meta name="robots" content="noindex"><link rel="stylesheet" href="site.css"><script src="site.js" defer></script></head>
<body style="--photo:url('assets/{photo}')"><a class="skip" href="#main">Skip to content</a><header class="header"><a class="brand" href="index.html">Wildflower<br>Collectives</a><button type="button" class="menu-button" data-open-menu aria-label="Open navigation" aria-haspopup="dialog" aria-controls="site-menu"><span></span><span></span><span></span></button></header>
<dialog class="menu" id="site-menu" aria-label="Navigation"><button class="menu-close" type="button" data-close-menu aria-label="Close navigation">×</button><nav aria-label="Main navigation">{links}</nav></dialog>
<main id="main" class="shell">{content}<footer><nav class="footer" aria-label="Footer navigation">{links}</nav><p class="copyright">© 2026 Wildflower Collectives</p></footer></main></body></html>'''
    (ROOT/file).write_text(html)

subtitle='A personal blog about the moments, people, and words that change us - and the healing and spiritual awakening we experience along the way.'
letters=''.join(f'<span aria-hidden="true">{c}</span>' for c in 'BUTTERFLY')
welcome=f'''<section class="welcome"><h1 aria-label="The Butterfly Effect"><span>THE</span><span class="rainbow">{letters}</span><span>EFFECT</span></h1><p>{subtitle}</p><a class="button" href="home.html">Come on in</a><a class="secondary" href="blog.html">Explore the blog</a></section>'''
page('index.html','The Butterfly Effect','eye.jpg',welcome,'Home')
page('welcome.html','The Butterfly Effect','eye.jpg',welcome,'Home')
intro='''<section class="intro" aria-label="The Butterfly Effect and this space"><div class="panel"><p>The butterfly effect is the idea that even <mark>the smallest actions</mark>, moments, emotions, or decisions can eventually lead to major changes later in life.</p><p>What may seem insignificant in one moment can create a <mark style="background:var(--blue)">ripple effect</mark> that alters an entire future. Emotionally and spiritually, it is often connected to <mark style="background:var(--lilac)">transformation, growth, healing, and becoming</mark>. Just like a butterfly goes through a complete transformation before it can fly, people also evolve through pain, change, endings, and self-discovery.</p><p>The butterfly effect reminds us that <mark style="background:var(--yellow)">small shifts</mark> - in mindset, healing, love, choices, or courage - can completely <mark style="background:var(--pink)">change the direction</mark> of someone's life over time.</p></div><div class="panel personal"><p>I’ve come to see my own life through this concept - how the <mark>people</mark> we meet, the <mark style="background:var(--blue)">words</mark> that stay with us, and the <mark style="background:var(--mint)">decisions</mark> we make can shape what comes next.</p><p>This is a personal blog about growth, healing, and what I’ve come to call my spiritual awakening. Through experiences from my past and what I’m learning along the way, I’m exploring how small shifts can move us toward the future we want for ourselves.</p><p>My hope is that you find something here that helps you feel understood and less alone in whatever you’re going through. Sometimes a few words can change how we see things, and what we take from them can change what we do next.</p></div><figure class="quote-figure"><a href="assets/coincidence.webp" data-open-quote aria-label="Read the complete Nothing is a coincidence quote"><img src="assets/coincidence.webp" alt="Nothing is a coincidence. No one crosses your path by chance. Some arrive as mirrors. Some as medicine. Some as messengers you won’t recognise until the lesson lands. Every encounter shifts something - a belief, a boundary, a version of you that needed to die or be reborn. The timing is never random. The soul orchestrates what the mind can’t explain. So pay attention to who appears when you think you’re done growing. They might be the reminder, the trigger, or the key that unlocks the next door."></a><figcaption>Tap to read full size ↗</figcaption></figure><a class="button full" href="blog.html" style="--accent:var(--yellow)">Enter the blog</a></section><dialog class="quote-dialog" id="quote-dialog" aria-label="Full quote artwork"><button type="button" data-close-quote>Close ×</button><img src="assets/coincidence.webp" alt="Full Nothing is a coincidence quote artwork. The full text is provided with the image on the introduction page."></dialog>'''
page('home.html','The Butterfly Effect','daisies.jpg',intro,'Home')

posts=[('still-becoming','still becoming.','I haven’t even met all of me yet.','On the parts of you still unfolding.','Life'),('permission-to-pivot','the permission to pivot.','You are allowed to change your mind.','When a different direction feels more like you.','Awakening')]
def card(post):
    slug,title,quote,description,cat=post
    return f'''<article class="post-card"><div class="quote-preview">“{quote}”</div><div class="draft-label">{cat.upper()} · DRAFT PREVIEW</div><h3>{title}</h3><p>{description}</p><a class="button full" href="reflection.html?post={slug}">Preview</a></article>'''
cards=''.join(map(card,posts))
page('blog.html','Blog','book.jpg',f'''<section class="page-hero"><h1>BLOG</h1><p>A place for my ruminating thoughts at night.</p><a class="secondary" href="#featured">Featured reflections ↓</a></section><section id="featured" class="panel"><p class="eyebrow">Featured</p><p class="draft-note">Preview selections - full reflections are being prepared.</p><div class="cards">{cards}</div></section><a class="button full" href="topics.html">Explore all topics</a>''','Blog')
topics=[('life','Life','The moments and choices that shape us.','peach'),('people','People','Connection, boundaries, and the people who change us.','mint'),('words','Words','The things we say. The things that stay.','pink'),('awakening','Awakening','Unlearning, noticing, and becoming.','blue')]
topiclinks=''.join(f'<a class="topic-link" href="{slug}.html" style="--accent:var(--{color})"><h2>{name}?</h2><p>{desc}</p></a>' for slug,name,desc,color in topics)
page('topics.html','What’s on your mind?','topics.jpg',f'''<section class="page-hero"><h1>what’s on<br>your mind?</h1></section><section class="topic-list" aria-label="Blog topics">{topiclinks}</section><div class="panel"><p>Or wander through everything.</p><a class="button full" href="all-posts.html">All posts</a></div>''','Blog')
for slug,name,desc,color in topics+[('all-posts','All posts','Browse every reflection.','lilac')]:
    tabs=''.join(f'<a href="{s}.html"'+(' aria-current="page"' if s==slug else '')+f'>{n}</a>' for s,n,d,c in topics)
    matches=[p for p in posts if p[4]==name] if slug!='all-posts' else posts
    body=''.join(map(card,matches)) if matches else '<div class="panel"><p>Reflections for this topic are coming soon.</p><a class="button full" href="topics.html">Explore another topic</a></div>'
    page(slug+'.html',name,'garden.jpg',f'<a class="back" href="topics.html">← All topics</a><section class="archive-heading"><h1>{name.lower()}.</h1><p>{desc}</p><nav class="tabs" aria-label="Filter by topic">{tabs}</nav></section><div class="cards">{body}</div>','Blog')
page('reflection.html','Reflection preview','book.jpg','''<a class="back" href="blog.html">← Back to Blog</a><section class="page-hero"><h1>still unfolding.</h1></section><div class="panel"><p class="eyebrow">Draft preview</p><p>The quote and post-card designs are in place. Kendall’s full reflection will be added here before publication.</p><a class="button full" href="topics.html">Explore the topics</a></div>''','Blog')
page('about.html','About Kendall','daisies.jpg','''<div class="portrait-placeholder" role="img" aria-label="Kendall’s portrait will be added here">Your photo goes here</div><section class="panel about-copy"><h1>a wild heart.<br>a curious mind.</h1><p>I’m Kendall, the person behind these reflections.</p><p>This is a space for growth, healing, spiritual curiosity, and the moments and words that change how we see things.</p><p class="draft-note">Portrait and fuller About introduction to come.</p><a class="button full" href="blog.html">Read the blog</a></section>''','About')
page('contact.html','Say hey','kindness.jpg','''<section class="page-hero"><h1>say hey.</h1></section><section class="panel"><p>I’d love to hear from you - whether it’s a thought, a question, or just to say hello.</p><form class="contact-form"><label for="name">Name</label><input id="name" name="name" autocomplete="name" disabled><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="email" disabled><label for="message">Message</label><textarea id="message" name="message" disabled></textarea><button class="button full" type="button" disabled>Send message</button><p class="draft-note">This form is a design preview. Message delivery will be connected before launch.</p></form></section>''','Contact')
print('Built',len(list(ROOT.glob('*.html'))),'connected HTML pages.')
